public void tempTick() {
    ItemStack mainHandStack = player.getEquippedStack(EquipmentSlot.MAINHAND);
    ItemStack offHandStack = player.getEquippedStack(EquipmentSlot.OFFHAND);
    if (player.age % tickRate == 0) {
        if (mainHandStack != ItemStack.EMPTY) {
            if (this.predicate.test(mainHandStack) && this.isActive() && !((ItemStackAccess)(Object)mainHandStack).isItemStackFood() && ((ItemStackAccess)(Object)mainHandStack).getItemStackFoodComponent() == null) {
                ItemStackFoodComponentUtil.setStackFood(mainHandStack, foodComponent, useAction, returnStack, sound);
            }
            if (this.predicate.test(mainHandStack) && !this.isActive() && ((ItemStackAccess)(Object)mainHandStack).getItemStackFoodComponent() == foodComponent) {
                ItemStackFoodComponentUtil.removeStackFood(mainHandStack);
            }
        }
        if (offHandStack != ItemStack.EMPTY) {
            if (this.predicate.test(offHandStack) && this.isActive() && !((ItemStackAccess)(Object)mainHandStack).isItemStackFood() && ((ItemStackAccess)(Object)mainHandStack).getItemStackFoodComponent() == null) {
                ItemStackFoodComponentUtil.setStackFood(offHandStack, foodComponent, useAction, returnStack, sound);
            }
            if (this.predicate.test(offHandStack) && !this.isActive() && ((ItemStackAccess)(Object)offHandStack).getItemStackFoodComponent() == foodComponent) {
                ItemStackFoodComponentUtil.removeStackFood(offHandStack);
            }
        }
    }
}

public void sendFoodComponentRemovePacket(@Nullable EquipmentSlot equipmentSlot, @Nullable StackFoodComponentUtil.InventoryLocation inventoryLocation, int inventoryIndex) {
    if (player.world.isClient()) return;
    PacketByteBuf buf = new PacketByteBuf(Unpooled.buffer());
    buf.writeInt(player.getEntityId());
    buf.writeBoolean(equipmentSlot != null);
    if (equipmentSlot != null) {
        buf.writeString(equipmentSlot.getName(), Short.MAX_VALUE);
    }

    buf.writeBoolean(inventoryLocation != null);
    if (inventoryLocation != null) {
        buf.writeByte(inventoryLocation.ordinal());
        buf.writeInt(inventoryIndex);
    }

    if (!(player instanceof ServerPlayerEntity)) return;
    sendPackets((ServerPlayerEntity) player, buf);
}

public EdibleItemPower(PowerType<?> type, PlayerEntity player, Predicate<ItemStack> predicate, FoodComponent foodComponent, UseAction useAction, ItemStack returnStack, SoundEvent sound, Consumer<Entity> entityActionWhenEaten, int tickRate) {
    super(type, player);
    this.predicate = predicate;
    this.foodComponent = foodComponent;
    this.useAction = useAction;
    this.returnStack = returnStack;
    this.sound = sound;
    this.entityActionWhenEaten = entityActionWhenEaten;
    this.tickRate = tickRate;
    this.setTicking(true);
}

@Inject(method = "baseTick", at = @At("HEAD"))
private void tick(CallbackInfo ci) {
    if (this.isDead() || !((LivingEntity)(Object)this instanceof PlayerEntity)) return;
    if (OriginComponent.hasPower(this, HoverPower.class)) {
        this.setVelocity(this.getVelocity().multiply(1.0, 0.0, 1.0));
        this.fallDistance = 0.0F;
    }
    ModComponents.getOriginComponent((PlayerEntity)(Object) this).getPowers(EdibleItemPower.class, true).forEach(EdibleItemPower::tempTick);
    if (OriginComponent.hasPower(this, BunnyHopPower.class) && !this.world.isClient) {
        BunnyHopPower bunnyHopPower = OriginComponent.getPowers(this, BunnyHopPower.class).get(0);
        if (framesOnGround > 4) {
            bunnyHopPower.setValue(0);
            OriginComponent.sync((PlayerEntity)(Object)this);
        }
        if (this.onGround || this.isTouchingWater() || this.isInLava() || this.hasVehicle() || this.isFallFlying()) {
            if (framesOnGround <= 4) {
                framesOnGround += 1;
            }
        } else {
            this.framesOnGround = 0;
        }
    }
}

public static void setStackFood(ItemStack stack, @Nullable FoodComponent component, @Nullable UseAction action, @Nullable ItemStack returnStack, @Nullable SoundEvent sound) {
    ((ItemStackAccess)(Object)stack).setItemStackFoodComponent(component);
    ((ItemStackAccess)(Object)stack).setFoodUseAction(action);
    ((ItemStackAccess)(Object)stack).setReturnStack(returnStack);
    ((ItemStackAccess)(Object)stack).setStackEatSound(sound);
}

public static void removeStackFood(ItemStack stack) {
    ((ItemStackAccess)(Object)stack).setItemStackFoodComponent(null);
    ((ItemStackAccess)(Object)stack).setFoodUseAction(null);
    ((ItemStackAccess)(Object)stack).setReturnStack(null);
    ((ItemStackAccess)(Object)stack).setStackEatSound(null);
}

@Override
public void setItemStackFoodComponent(FoodComponent stackFoodComponent) {
    this.stackFoodComponent = stackFoodComponent;
}

@Override
public FoodComponent getItemStackFoodComponent() {
    return this.stackFoodComponent;
}

@Override
public boolean isItemStackFood() {
    return this.stackFoodComponent != null;
}

@Override
public void setFoodUseAction(UseAction useAction) {
    if (useAction == UseAction.EAT || useAction == UseAction.DRINK) {
        this.useAction = useAction;
    }
}

@Override
public void setReturnStack(ItemStack stack) {
    this.returnStack = stack;
}

@Override
public void setStackEatSound(SoundEvent sound) {
    this.eatSound = sound;
}

@Inject(method = "getUseAction", at = @At("HEAD"), cancellable = true)
private void getUseAction(CallbackInfoReturnable<UseAction> cir) {
    if (this.isItemStackFood()) {
        cir.setReturnValue(this.getFoodUseAction() != null ? this.getFoodUseAction() : UseAction.EAT);
    }
}

@Inject(method = "getMaxUseTime", at = @At("HEAD"), cancellable = true)
private void getMaxUseTime(CallbackInfoReturnable<Integer> cir) {
    if (isItemStackFood()) {
        cir.setReturnValue(this.getItemStackFoodComponent().isSnack() ? 16 : 32);
    }
}

@Inject(method = "finishUsing", at = @At("HEAD"), cancellable = true)
private void finishUsing(World world, LivingEntity user, CallbackInfoReturnable<ItemStack> cir) {
    if (!(user instanceof PlayerEntity)) return;
    if (this.isItemStackFood()) {
        OriginComponent.getPowers(user, EdibleItemPower.class).stream().filter(p -> p.doesApply((ItemStack)(Object)this)).forEach(EdibleItemPower::eat);
        if (this.getReturnStack() != null) {
            cir.setReturnValue(user instanceof PlayerEntity && ((PlayerEntity)user).abilities.creativeMode ? user.eatFood(world, (ItemStack)(Object)this) : this.getReturnStack());
        }
        cir.setReturnValue(user.eatFood(world, (ItemStack)(Object)this));
    }
}

@Inject(method = "copy", at = @At("RETURN"))
private void copyFoodComponent(CallbackInfoReturnable<ItemStack> cir) {
    if (this.isItemStackFood()) {
        ItemStackFoodComponentUtil.setStackFood(cir.getReturnValue(), this.stackFoodComponent, this.useAction, this.returnStack, this.eatSound);
    }
}

public static void sendPackets(ServerPlayerEntity player, PacketByteBuf buf) {
    if (GameInstance.getServer() != null) {
        for (ServerWorld serverWorld : GameInstance.getServer().getWorlds()) {
            NetworkManager.sendToPlayers(serverWorld.getPlayers(), ApugliPackets.REMOVE_STACK_FOOD_COMPONENT, buf);
        }
    }

    NetworkManager.sendToPlayer(player, ApugliPackets.REMOVE_STACK_FOOD_COMPONENT, buf);
}

private static void onFoodComponentSync(PacketByteBuf packetByteBuf, NetworkManager.PacketContext context) {
    int targetId = packetByteBuf.readInt();

    boolean usesEquipmentSlot = packetByteBuf.readBoolean();
    String equipmentSlotId = "";
    if (usesEquipmentSlot) {
        equipmentSlotId = packetByteBuf.readString(Short.MAX_VALUE);
    }
    String finalEquipmentSlotId = equipmentSlotId;

    boolean usesInventoryIndex = packetByteBuf.readBoolean();
    StackFoodComponentUtil.InventoryLocation inventoryLocation = null;
    int inventoryIndex = 0;
    if (usesInventoryIndex) {
        inventoryLocation = StackFoodComponentUtil.InventoryLocation.values()[packetByteBuf.readByte()];
        inventoryIndex = packetByteBuf.readInt();
    }
    StackFoodComponentUtil.InventoryLocation finalInventoryLocation = inventoryLocation;
    int finalInventoryIndex = inventoryIndex;

    context.queue(() -> {
        Entity entity = context.getPlayer().getEntityWorld().getEntityById(targetId);
        if (!(entity instanceof PlayerEntity)) {
            Apugli.LOGGER.warn("Received unknown target");
        }  else {
            if (usesEquipmentSlot) {
                EquipmentSlot equipmentSlot = EquipmentSlot.byName(finalEquipmentSlotId);
                ItemStack stack = ((PlayerEntity)entity).getEquippedStack(equipmentSlot);
                ItemStackFoodComponentUtil.removeStackFood(stack);
            }
            if (usesInventoryIndex) {
                DefaultedList<ItemStack> inventory;
                switch(finalInventoryLocation) {
                    case MAIN:
                        inventory = ((PlayerEntity) entity).inventory.main;
                        break;
                    case ARMOR:
                        inventory = ((PlayerEntity) entity).inventory.armor;
                        break;
                    case OFFHAND:
                        inventory = ((PlayerEntity) entity).inventory.offHand;
                        break;
                    default:
                        throw new IllegalStateException("Unexpected value: " + finalInventoryLocation);
                }
                ItemStackFoodComponentUtil.removeStackFood(inventory.get(finalInventoryIndex));
            }
        }
    });
}

